[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "wifi-details-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "wifi-details-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "title"
              },
              {
                "id": "details_card"
              },
              {
                "id": "actions_title"
              },
              {
                "id": "connect_button"
              }
            ],
            "padding": {
              "all": 16
            },
            "spacing": 16
          }
        },
        {
          "id": "title",
          "type": "Text",
          "properties": {
            "text": "Wi-Fi Network Details",
            "style": "title"
          }
        },
        {
          "id": "details_card",
          "type": "Card",
          "properties": {
            "child": {
              "id": "details_list"
            }
          }
        },
        {
          "id": "details_list",
          "type": "List",
          "properties": {
            "children": [
              {
                "id": "network_name_row"
              },
              {
                "id": "security_type_row"
              },
              {
                "id": "password_row"
              }
            ]
          }
        },
        {
          "id": "network_name_row",
          "type": "Row",
          "properties": {
            "children": [
              {
                "id": "network_name_label"
              },
              {
                "id": "network_name_value"
              }
            ],
            "mainAxisAlignment": "spaceBetween"
          }
        },
        {
          "id": "network_name_label",
          "type": "Text",
          "properties": {
            "text": "Network Name",
            "style": "label"
          }
        },
        {
          "id": "network_name_value",
          "type": "Text",
          "properties": {
            "text": "CoffeeShop_Guest"
          }
        },
        {
          "id": "security_type_row",
          "type": "Row",
          "properties": {
            "children": [
              {
                "id": "security_type_label"
              },
              {
                "id": "security_type_value"
              }
            ],
            "mainAxisAlignment": "spaceBetween"
          }
        },
        {
          "id": "security_type_label",
          "type": "Text",
          "properties": {
            "text": "Security Type",
            "style": "label"
          }
        },
        {
          "id": "security_type_value",
          "type": "Text",
          "properties": {
            "text": "WPA"
          }
        },
        {
          "id": "password_row",
          "type": "Row",
          "properties": {
            "children": [
              {
                "id": "password_label"
              },
              {
                "id": "password_value"
              }
            ],
            "mainAxisAlignment": "spaceBetween"
          }
        },
        {
          "id": "password_label",
          "type": "Text",
          "properties": {
            "text": "Password",
            "style": "label"
          }
        },
        {
          "id": "password_value",
          "type": "Text",
          "properties": {
            "text": "LatteArt2024"
          }
        },
        {
          "id": "actions_title",
          "type": "Text",
          "properties": {
            "text": "Quick Actions",
            "style": "subheading"
          }
        },
        {
          "id": "connect_button",
          "type": "Button",
          "properties": {
            "label": "Connect Now",
            "style": "primary",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "parameters": {
                  "url": "https://example.com/connect-wifi"
                }
              }
            }
          }
        }
      ]
    }
  }
]
